<?php require __DIR__.'/../app/bootstrap.php';require_admin();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="workshop-interest-submissions.csv"');echo "\xEF\xBB\xBF";$f=array_column(interest_form_definition()['fields'],'id');$o=fopen('php://output','w');fputcsv($o,array_merge(['id','created_at','name','email','country'],$f));foreach(database()->query('SELECT * FROM interest_submissions ORDER BY id DESC') as $r){$p=json_decode($r['payload_json'],true)?:[];$line=[$r['id'],$r['created_at'],$r['name'],$r['email'],$r['country']];foreach($f as $id)$line[]=$p[$id]??'';fputcsv($o,$line);}
